// @FIGURE_CODE_BEGIN
const W = 900;
const H = 550;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);
draw.rect(W, H).fill('#ffffff').back();

// Colors
const PROTON = '#7fb842';
const PROTON_DARK = '#5c8a2e';
const NEUTRON = '#d9d9d9';
const NEUTRON_DARK = '#a6a6a6';

// Markers
const defs = draw.defs();
const arrowMarker = defs.marker(10, 8, function(add) {
  add.path('M0,0 L10,4 L0,8 Z').fill('#222');
}).ref(8, 4);

// Groups for states
const reactantsG = draw.group();
const intermediateG = draw.group();
const productsG = draw.group();
const gen2G = draw.group();
const gen3G = draw.group();
const eqG = draw.group();

const eqReact = eqG.group();
const eqArr1 = eqG.group();
const eqInter = eqG.group();
const eqArr2 = eqG.group();
const eqProd = eqG.group();

// Helpers
function drawSphere(g, cx, cy, r, color, darkColor) {
  g.circle(r*2).center(cx, cy).fill(darkColor);
  g.circle(r*1.5).center(cx - r*0.2, cy - r*0.2).fill(color);
  g.circle(r*0.6).center(cx - r*0.4, cy - r*0.4).fill('#ffffff').opacity(0.8);
}

function drawCluster(g, cx, cy, radius, pCount, nCount, type) {
  const cluster = g.group();
  const N = Math.floor((pCount + nCount) * 0.4); 
  const pTotal = Math.floor(pCount * 0.4);
  const rSphere = radius * 0.35;

  if (type === 'peanut') {
    const pr = radius * 0.9;
    const dy = radius * 0.65;
    cluster.path(`M ${cx-pr},${cy-dy} A ${pr},${pr} 0 1,1 ${cx+pr},${cy-dy} Q ${cx+pr*0.7},${cy} ${cx+pr},${cy+dy} A ${pr},${pr} 0 1,1 ${cx-pr},${cy+dy} Q ${cx-pr*0.7},${cy} ${cx-pr},${cy-dy} Z`)
     .fill('#fff').stroke({width: 4, color: '#d93b3b'});
  }

  let spheres = [];
  if (type === 'peanut') {
    for (let i = 0; i < N; i++) {
      const lobe = i % 2;
      const index = Math.floor(i/2);
      const N_lobe = Math.floor(N/2);
      const r_i = radius * 0.8 * Math.sqrt(index / N_lobe);
      const theta = index * 2.4;
      const x = cx + r_i * Math.cos(theta) * 0.8;
      const lobeY = (lobe === 0 ? -1 : 1) * radius * 0.6;
      const y = cy + lobeY + r_i * Math.sin(theta);
      spheres.push({x, y, isProton: (i * 7) % N < pTotal});
    }
  } else {
    for (let i = 0; i < N; i++) {
      const r_i = radius * 0.9 * Math.sqrt(i / N);
      const theta = i * 2.4;
      const x = cx + r_i * Math.cos(theta);
      const y = cy + r_i * Math.sin(theta);
      spheres.push({x, y, isProton: (i * 7) % N < pTotal});
    }
  }

  spheres.sort((a,b) => a.y - b.y);

  spheres.forEach(s => {
    const color = s.isProton ? PROTON : NEUTRON;
    const darkColor = s.isProton ? PROTON_DARK : NEUTRON_DARK;
    drawSphere(cluster, s.x, s.y, rSphere, color, darkColor);
  });
  return cluster;
}

function drawMiniU235(g, cx, cy, r) {
  g.circle(r*2).center(cx, cy).fill(PROTON).stroke({width: 1, color: PROTON_DARK});
  g.circle(r*0.6).center(cx - r*0.4, cy - r*0.2).fill(NEUTRON);
  g.circle(r*0.5).center(cx + r*0.2, cy + r*0.4).fill(NEUTRON);
  g.circle(r*0.4).center(cx + r*0.3, cy - r*0.4).fill(NEUTRON);
}

function drawArrow(g, x1, y1, x2, y2) {
  g.line(x1, y1, x2, y2).stroke({width: 2, color: '#222'}).marker('end', arrowMarker);
}

function drawIsotopeText(g, x, y, mass, atomic, symbol, extra) {
  g.text(mass).font({ size: 12, family: 'sans-serif' }).move(x, y - 14).attr('text-anchor', 'end');
  g.text(atomic).font({ size: 12, family: 'sans-serif' }).move(x, y + 2).attr('text-anchor', 'end');
  g.text(symbol).font({ size: 20, family: 'sans-serif' }).move(x + 4, y - 12);
  if (extra) {
    g.text(extra).font({ size: 14, family: 'sans-serif' }).move(x - 20, y + 25);
  }
}

function addEqText(g, x, y, mass, atomic, symbol) {
  g.text(mass).font({size:11, family:'sans-serif'}).move(x, y-14).attr('text-anchor','end');
  g.text(atomic).font({size:11, family:'sans-serif'}).move(x, y+2).attr('text-anchor','end');
  g.text(symbol).font({size:18, family:'sans-serif'}).move(x+2, y-12);
}

function drawStarburst(g, cx, cy) {
  const group = g.group();
  let pts1 = [], pts2 = [];
  for(let i=0; i<16; i++) {
    const angle = (i/16) * Math.PI * 2;
    const r1 = i%2 === 0 ? 65 : 25;
    pts1.push([cx + r1*Math.cos(angle), cy + r1*Math.sin(angle)]);
    const r2 = i%2 === 0 ? 40 : 15;
    const a2 = angle + 0.1;
    pts2.push([cx + r2*Math.cos(a2), cy + r2*Math.sin(a2)]);
  }
  group.polygon(pts1).fill('#fada5e').stroke({width: 1, color: '#e5b912'});
  group.polygon(pts2).fill('#fff3b0');

  const eText = group.text('Energy').font({size: 15, weight: 'bold', family: 'sans-serif'}).center(cx, cy);
  eText.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return group;
}

function addHitbox(g, cx, cy, r, tooltipText, popupTitle, popupBody) {
  g.circle(r*2).center(cx, cy).fill('transparent').css('cursor', 'pointer')
   .on('mousemove', e => showTooltip(tooltipText, e))
   .on('mouseleave', () => hideTooltip())
   .on('click', () => showPopup(popupTitle, popupBody));
}

// --- DRAWING STAGE 1: REACTANTS ---
reactantsG.line(16, 220, 27, 220).stroke({width: 2, color: '#aaa'});
reactantsG.line(18, 212, 25, 216).stroke({width: 2, color: '#aaa'});
reactantsG.line(18, 228, 25, 224).stroke({width: 2, color: '#aaa'});
drawSphere(reactantsG, 40, 220, 10, NEUTRON, NEUTRON_DARK);
drawIsotopeText(reactantsG, 40, 245, '1', '0', 'n');
drawCluster(reactantsG, 150, 220, 60, 92, 143, 'circle');
drawIsotopeText(reactantsG, 150, 295, '235', '92', 'U');
drawArrow(reactantsG, 60, 220, 82, 220);
addHitbox(reactantsG, 40, 220, 25, "Neutron (1/0 n)", "Incoming Neutron", "A single, relatively slow-moving neutron initiates the reaction. Neutrons are ideal projectiles because they have no electrical charge and aren't repelled by the positively charged nucleus.");
addHitbox(reactantsG, 150, 220, 65, "Uranium-235 Nucleus", "Uranium-235", "U-235 has 92 protons and 143 neutrons (total mass 235). It is a fissile isotope, meaning it can sustain a nuclear chain reaction when struck by a slow neutron.");

// --- DRAWING STAGE 2: INTERMEDIATE ---
intermediateG.line(260, 220, 245, 220).stroke({width:2, color:'#aaa'});
intermediateG.line(265, 205, 250, 195).stroke({width:2, color:'#aaa'});
intermediateG.line(265, 235, 250, 245).stroke({width:2, color:'#aaa'});
drawArrow(intermediateG, 225, 220, 250, 220);
drawCluster(intermediateG, 320, 220, 60, 92, 144, 'peanut');
drawIsotopeText(intermediateG, 320, 310, '236', '92', 'U', 'Unstable nucleus');
addHitbox(intermediateG, 320, 220, 75, "Uranium-236 (Unstable)", "Unstable Intermediate (U-236)", "When U-235 absorbs the neutron, it momentarily becomes U-236. This extra mass and energy make the nucleus wildly unstable, causing it to deform into a peanut shape and snap apart almost instantly.");

// --- DRAWING STAGE 3: PRODUCTS ---
drawArrow(productsG, 385, 185, 435, 125);
drawArrow(productsG, 385, 255, 435, 315);
drawCluster(productsG, 480, 90, 35, 36, 56, 'circle');
drawIsotopeText(productsG, 480, 35, '92', '36', 'Kr');
drawCluster(productsG, 480, 350, 45, 56, 85, 'circle');
drawIsotopeText(productsG, 480, 410, '141', '56', 'Ba');
drawStarburst(productsG, 420, 220);
drawArrow(productsG, 465, 195, 520, 145);
drawArrow(productsG, 480, 220, 520, 220);
drawArrow(productsG, 465, 245, 520, 295);
drawSphere(productsG, 540, 140, 10, NEUTRON, NEUTRON_DARK);
drawSphere(productsG, 540, 220, 10, NEUTRON, NEUTRON_DARK);
drawSphere(productsG, 540, 300, 10, NEUTRON, NEUTRON_DARK);
drawIsotopeText(productsG, 580, 210, '1', '0', 'n');
productsG.text('3').font({size: 20, family: 'sans-serif'}).move(560, 198);
addHitbox(productsG, 480, 90, 45, "Krypton-92", "Fission Product: Kr-92", "Krypton-92 is one of the two smaller daughter nuclei produced. Notice mass is conserved: 92 (Kr) + 141 (Ba) + 3 (neutrons) = 236.");
addHitbox(productsG, 480, 350, 55, "Barium-141", "Fission Product: Ba-141", "Barium-141 is the other daughter nucleus. The exact products can vary, but Ba-141 and Kr-92 are a very common pair in U-235 fission.");
addHitbox(productsG, 420, 220, 50, "Energy Released", "Binding Energy", "The combined mass of the products is slightly less than the initial U-236. This missing mass ('mass defect') is converted directly into an enormous amount of kinetic and electromagnetic energy, following E = mc².");
addHitbox(productsG, 540, 220, 90, "3 Ejected Neutrons", "Chain Reaction Drivers", "The fission event releases 3 free neutrons. If these hit other U-235 nuclei, they trigger more fissions. Because 1 reaction produces 3 neutrons, the reaction grows exponentially.");

// --- CASCADE GENERATION 2 & 3 ---
const gen2_y = [140, 220, 300];
const gen2_sub_offsets = [-30, 0, 30];
const gen3_sub_offsets = [-10, 0, 10];

gen2_y.forEach(y => {
  drawArrow(gen2G, 560, y, 595, y);
  drawMiniU235(gen2G, 620, y, 20);
  gen2_sub_offsets.forEach(off => {
    let sy = y + off;
    drawArrow(gen2G, 645, y, 685, sy);
    drawSphere(gen2G, 700, sy, 6, NEUTRON, NEUTRON_DARK);
  });
});

