    const pr = radius * 0.9;
    const dy = radius * 0.65;
    cluster.path(`M ${cx-pr},${cy-dy} A ${pr},${pr} 0 1,1 ${cx+pr},${cy-dy} Q ${cx+pr*0.7},${cy} ${cx+pr},${cy+dy} A ${pr},${pr} 0 1,1 ${cx-pr},${cy+dy} Q ${cx-pr*0.7},${cy} ${cx-pr},${cy-dy} Z`)
     .fill('#fff').stroke({width: 4, color: '#d93b3b'});
  }

  let spheres = [];
  if (type === 'peanut') {
    for (let i = 0; i < N; i++) {
      const lobe = i % 2;
      const index = Math.floor(i/2);
      const N_lobe = Math.floor(N/2);
      const r_i = radius * 0.8 * Math.sqrt(index / N_lobe);
      const theta = index * 2.4;
      const x = cx + r_i * Math.cos(theta) * 0.8;
      const lobeY = (lobe === 0 ? -1 : 1) * radius * 0.6;
      const y = cy + lobeY + r_i * Math.sin(theta);
      spheres.push({x, y, isProton: (i * 7) % N < pTotal});
    }
  } else {
    for (let i = 0; i < N; i++) {
      const r_i = radius * 0.9 * Math.sqrt(i / N);
      const theta = i * 2.4;
      const x = cx + r_i * Math.cos(theta);
      const y = cy + r_i * Math.sin(theta);
      spheres.push({x, y, isProton: (i * 7) % N < pTotal});
    }
  }

  spheres.sort((a,b) => a.y - b.y);

  spheres.forEach(s => {
    const color = s.isProton ? PROTON : NEUTRON;
    const darkColor = s.isProton ? PROTON_DARK : NEUTRON_DARK;
    drawSphere(cluster, s.x, s.y, rSphere, color, darkColor);
  });
  return cluster;
}

function drawMiniU235(g, cx, cy, r) {
  g.circle(r*2).center(cx, cy).fill(PROTON).stroke({width: 1, color: PROTON_DARK});
  g.circle(r*0.6).center(cx - r*0.4, cy - r*0.2).fill(NEUTRON);
  g.circle(r*0.5).center(cx + r*0.2, cy + r*0.4).fill(NEUTRON);
  g.circle(r*0.4).center(cx + r*0.3, cy - r*0.4).fill(NEUTRON);
}

function drawArrow(g, x1, y1, x2, y2) {
