// @FIGURE_CODE_BEGIN
const W = 900;
const H = 520;
const draw = SVG().addTo('#container').size('100%', '100%').viewbox(0, 0, W, H);

// Colors
const PROTON = '#8cc63f';
const PROTON_DARK = '#659728';
const NEUTRON = '#e6e6e6';
const NEUTRON_DARK = '#b3b3b3';

// Markers
const defs = draw.defs();
const arrowMarker = defs.marker(10, 8, function(add) {
  add.path('M0,0 L10,4 L0,8 Z').fill('#222');
}).ref(8, 4);

// Groups for states (ordered for painter's algorithm)
const reactantsG = draw.group();
const intermediateG = draw.group();
const productsG = draw.group();
const eqG = draw.group();
const hitboxes = draw.group();

// Helpers
function drawSphere(g, cx, cy, r, color, darkColor) {
  g.circle(r*2).center(cx, cy).fill(darkColor);
  g.circle(r*1.5).center(cx - r*0.2, cy - r*0.2).fill(color);
  g.circle(r*0.5).center(cx - r*0.3, cy - r*0.3).fill('#ffffff').opacity(0.8);
}

function drawCluster(g, cx, cy, radius, pCount, nCount, type) {
  const cluster = g.group();
  const N = Math.floor((pCount + nCount) * 0.45); 
  const pTotal = Math.floor(pCount * 0.45);
  const rSphere = radius * 0.22; 

  if (type === 'peanut') {
    const pr = radius * 0.9;
    const dy = radius * 0.75;
    // Pure stroke path to create a subtle red halo indicating instability (no solid white fill)
    const peanutPath = `M ${cx-pr*0.8},${cy-dy} 
                        A ${pr*0.9},${pr*0.9} 0 1,1 ${cx+pr*0.8},${cy-dy} 
                        Q ${cx+pr*0.4},${cy} ${cx+pr*0.8},${cy+dy} 
                        A ${pr*0.9},${pr*0.9} 0 1,1 ${cx-pr*0.8},${cy+dy} 
                        Q ${cx-pr*0.4},${cy} ${cx-pr*0.8},${cy-dy} Z`;
    cluster.path(peanutPath).fill('none').stroke({width: 14, color: '#ff4d4d', opacity: 0.35, linejoin: 'round'});
  }

  let spheres = [];
  if (type === 'peanut') {
    for (let i = 0; i < N; i++) {
      const lobe = i % 2; 
      const index = Math.floor(i/2);
      const N_lobe = Math.floor(N/2);
      const r_i = radius * 0.8 * Math.sqrt((index+0.5) / N_lobe);
      const theta = index * 2.39996;
      const x = cx + r_i * Math.cos(theta) * 0.85;
      const lobeY = (lobe === 0 ? -1 : 1) * radius * 0.65;
      const y = cy + lobeY + r_i * Math.sin(theta);
      spheres.push({x, y, isProton: (i * 7) % N < pTotal});
    }
  } else {
    for (let i = 0; i < N; i++) {
      const r_i = radius * 0.95 * Math.sqrt((i+0.5) / N);
      const theta = i * 2.39996;
      const x = cx + r_i * Math.cos(theta);
      const y = cy + r_i * Math.sin(theta);
      spheres.push({x, y, isProton: (i * 7) % N < pTotal});
    }
  }

  // Sort by Y to simulate correct overlaps
  spheres.sort((a,b) => a.y - b.y);
  spheres.forEach(s => {
    const color = s.isProton ? PROTON : NEUTRON;
    const darkColor = s.isProton ? PROTON_DARK : NEUTRON_DARK;
    drawSphere(cluster, s.x, s.y, rSphere, color, darkColor);
  });
  return cluster;
}

function drawArrow(g, x1, y1, x2, y2) {
  g.line(x1, y1, x2, y2).stroke({width: 2, color: '#222'}).marker('end', arrowMarker);
}

function drawIsotopeText(g, x, y, mass, atomic, symbol, extra = '') {
  const tG = g.group();
  tG.text(mass).font({ size: 15, family: 'sans-serif' }).move(-4, -22).attr('text-anchor', 'end');
  tG.text(atomic).font({ size: 15, family: 'sans-serif' }).move(-4, 4).attr('text-anchor', 'end');
  tG.text(symbol).font({ size: 30, family: 'sans-serif' }).move(0, -22);
  if (extra) {
    tG.text(extra).font({ size: 16, family: 'sans-serif' }).move(8, 32).attr('text-anchor', 'middle');
  }
  tG.move(x, y);
}

function drawStarburst(g, cx, cy) {
  const group = g.group();
  let pts1 = [], pts2 = [];
  for(let i=0; i<16; i++) {
    const angle = (i/16) * Math.PI * 2;
    const r1 = i%2 === 0 ? 75 : 22;
    pts1.push([cx + r1*Math.cos(angle), cy + r1*Math.sin(angle)]);
    const r2 = i%2 === 0 ? 50 : 12;
    const a2 = angle + 0.1;
    pts2.push([cx + r2*Math.cos(a2), cy + r2*Math.sin(a2)]);
  }
  group.polygon(pts1).fill('#fce883').stroke({width: 1, color: '#e5b912'});
  group.polygon(pts2).fill('#fff3b0');

  const eText = group.text('Energy').font({size: 16, weight: 'bold', family: 'sans-serif'}).move(cx, cy - 10).attr('text-anchor', 'middle');
  eText.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
  return group;
}

function addHitbox(g, cx, cy, rx, ry, tooltipText, popupTitle, popupBody) {
  g.ellipse(rx*2, ry*2).center(cx, cy).fill('transparent').css('cursor', 'pointer')
   .on('mousemove', e => showTooltip(tooltipText, e))
   .on('mouseleave', () => hideTooltip())
   .on('click', () => showPopup(popupTitle, popupBody));
}

// --- STAGE 1: REACTANTS ---
drawSphere(reactantsG, 50, 200, 10, NEUTRON, NEUTRON_DARK);
reactantsG.text('1').font({ size: 12, family: 'sans-serif' }).move(40, 220).attr('text-anchor', 'end');
reactantsG.text('0').font({ size: 12, family: 'sans-serif' }).move(40, 235).attr('text-anchor', 'end');
reactantsG.text('n').font({ size: 18, family: 'sans-serif' }).move(44, 220);

drawArrow(reactantsG, 75, 200, 105, 200);

drawCluster(reactantsG, 180, 200, 65, 92, 143, 'circle');
drawIsotopeText(reactantsG, 165, 310, '235', '92', 'U'); // Moved down for complete clearance

addHitbox(hitboxes, 50, 200, 25, 25, "Incoming Neutron", "Incoming Neutron", "A slow-moving neutron initiates the reaction. Neutrons have no charge, so they aren't repelled by the positively charged nucleus.");
addHitbox(hitboxes, 180, 200, 65, 65, "Uranium-235", "Uranium-235 Nucleus", "U-235 has 92 protons and 143 neutrons. It is a fissile isotope, meaning it can sustain a chain reaction when struck by a neutron.");

// --- STAGE 2: INTERMEDIATE ---
drawArrow(intermediateG, 265, 200, 340, 200);
drawCluster(intermediateG, 430, 200, 70, 92, 144, 'peanut');
drawIsotopeText(intermediateG, 415, 355, '236', '92', 'U', 'Unstable nucleus'); // Moved down safely below peanut

addHitbox(hitboxes, 430, 200, 70, 105, "Uranium-236 (Unstable)", "Unstable Intermediate (U-236)", "Absorbing a neutron turns U-235 into U-236. The extra energy makes it violently unstable, deforming into a peanut shape before snapping apart.");

// --- STAGE 3: PRODUCTS ---
drawArrow(productsG, 490, 160, 590, 110);
drawArrow(productsG, 490, 240, 590, 290);

drawStarburst(productsG, 560, 200);

drawArrow(productsG, 620, 180, 725, 155);
drawArrow(productsG, 630, 200, 745, 200);
drawArrow(productsG, 620, 220, 725, 245);

drawCluster(productsG, 690, 90, 45, 36, 56, 'circle');
drawIsotopeText(productsG, 760, 80, '92', '36', 'Kr');

drawCluster(productsG, 690, 330, 55, 56, 85, 'circle');
drawIsotopeText(productsG, 760, 320, '141', '56', 'Ba');

drawSphere(productsG, 760, 150, 10, NEUTRON, NEUTRON_DARK);
drawSphere(productsG, 780, 200, 10, NEUTRON, NEUTRON_DARK);
drawSphere(productsG, 760, 250, 10, NEUTRON, NEUTRON_DARK);

const nLabelG = productsG.group();
nLabelG.text('3').font({size: 26, family: 'sans-serif'}).move(810, 185);
nLabelG.text('1').font({ size: 14, family: 'sans-serif' }).move(838, 185).attr('text-anchor', 'end');
nLabelG.text('0').font({ size: 14, family: 'sans-serif' }).move(838, 205).attr('text-anchor', 'end');
nLabelG.text('n').font({ size: 26, family: 'sans-serif' }).move(842, 185);

addHitbox(hitboxes, 690, 90, 45, 45, "Krypton-92", "Fission Product: Kr-92", "Krypton-92 is one of the two smaller daughter nuclei produced. Notice mass is conserved: 92 (Kr) + 141 (Ba) + 3 (neutrons) = 236.");
addHitbox(hitboxes, 690, 330, 55, 55, "Barium-141", "Fission Product: Ba-141", "Barium-141 is the other daughter nucleus. The exact products can vary, but Ba-141 and Kr-92 are a very common pair.");
addHitbox(hitboxes, 560, 200, 55, 55, "Energy Released", "Binding Energy", "The combined mass of the products is slightly less than U-236. The missing mass ('mass defect') is converted directly into an enormous amount of energy (E = mc²).");
addHitbox(hitboxes, 780, 200, 45, 75, "3 Ejected Neutrons", "New Neutrons", "The fission event releases 3 free neutrons. If these hit other U-235 nuclei, they trigger more fissions, creating a chain reaction.");

// --- HORIZONTALLY CENTERED NUCLEAR EQUATION ---
let currX = 0;

function addTerm(parent, mass, atomic, symbol, preText = '') {
  const g = parent.group();
  let startX = 0;
  if (preText) {
    g.text(preText).font({size: 26, family: 'sans-serif'}).move(0, -18);
    startX = 18;
  }
  g.text(mass).font({size: 15, family: 'sans-serif'}).move(startX, -25).attr('text-anchor', 'end');
  g.text(atomic).font({size: 15, family: 'sans-serif'}).move(startX, 1).attr('text-anchor', 'end');
  g.text(symbol).font({size: 30, family: 'sans-serif'}).move(startX + 4, -25);
  const bbox = g.bbox();
  g.move(currX, 0); 
  currX += bbox.width + 22; 
  return g;
}

function addOp(parent, str) {
  const g = parent.group();
  g.text(str).font({size: 26, family: 'sans-serif'}).move(0, -18);
  g.move(currX, 0);
  currX += g.bbox().width + 22;
  return g;
}

const eqReact = eqG.group();
addTerm(eqReact, '235', '92', 'U');
addOp(eqReact, '+');
addTerm(eqReact, '1', '0', 'n');

const eqArr1 = eqG.group();
addOp(eqArr1, '→');

const eqInter = eqG.group();
addTerm(eqInter, '236', '92', 'U');

const eqArr2 = eqG.group();
addOp(eqArr2, '→');

const eqProd = eqG.group();
addTerm(eqProd, '141', '56', 'Ba');
addOp(eqProd, '+');
addTerm(eqProd, '92', '36', 'Kr');
addOp(eqProd, '+');
addTerm(eqProd, '1', '0', 'n', '3'); 

const eqBbox = eqG.bbox();
eqG.move(W/2 - eqBbox.width/2, 470);

// --- INTERACTIVITY LOGIC ---
let currentFissionPhase = 'All Stages';

function applyVisibilities() {
  const p = currentFissionPhase;
  const o_react = (p === 'All Stages' || p === 'Reactants') ? 1 : 0.15;
  const o_inter = (p === 'All Stages' || p === 'Unstable Intermediate') ? 1 : 0.15;
  const o_prod  = (p === 'All Stages' || p === 'Products') ? 1 : 0.15;

  const t = 400; 
  reactantsG.animate(t).opacity(o_react);
  eqReact.animate(t).opacity(o_react);
  eqArr1.animate(t).opacity(o_react);

  intermediateG.animate(t).opacity(o_inter);
  eqInter.animate(t).opacity(o_inter);
  eqArr2.animate(t).opacity(o_inter);

  productsG.animate(t).opacity(o_prod);
  eqProd.animate(t).opacity(o_prod);
}

window.update_fissionPhase = function(val) {
  currentFissionPhase = val;
  ['all','react','inter','prod'].forEach(id => {
    const el = document.getElementById('btn_'+id);
    if(el) el.classList.remove('active');
  });
  if(val === 'All Stages') document.getElementById('btn_all').classList.add('active');
